Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_prepend_resize_failure(void) {
    // Setup: create a buffer with content "World" (len=5), buffer size=5+1=6
    buffer_t *buf = helper_create_buffer_with_content("World");
    TEST_ASSERT_NOT_NULL(buf);

    // The buffer's allocated size is just enough for "World" (5 chars + '\0')
    // Prepending "Hello" (len=5) will require resizing: needed = 5+5=10 > 6
    // We want buffer_resize to fail, which is the first allocation after setup (2 allocs in setup)
    malloc_fail_after(2); // Fail the next allocation (realloc in buffer_resize)

    int ret = buffer_prepend(buf, "Hello");
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should remain unchanged
    helper_assert_buffer_content(buf, "World");
    helper_assert_buffer_length(buf, 5);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_failure);
    return UNITY_END();
}


